<template>
    <div class="color-picker" ref="pickerRef" @change="updateValue">
      <div
        class="color-button"
        :style="{
          backgroundColor: modelValue,
          width: btnwidth,
          height: btnheight
        }"
        @click="togglePicker"
      ></div>
      <div v-if="isOpen" class="picker-popup">
        <Chrome id="vueColor" v-model="internalColor" ></Chrome>
      </div>
    </div>
  </template>
  
  <script setup>
  import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
  import { Chrome } from '@ckpack/vue-color'
  
  const props = defineProps({
    modelValue: {
      type: String,
      required: true,
      default: '#000000' // or any other default color you prefer
    },
    btnwidth: {
      type: String,
      default: '30px'
    },
    btnheight: {
      type: String,
      default: '20px'
    },
    // New props for x and y offsets
    xOffset: {
      type: Number,
      default: 0
    },
    yOffset: {
      type: Number,
      default: 0
    }
  })

  const internalColor = ref("#00ff00");
  
  const emit = defineEmits(['update:modelValue', 'changed'])
  
  const isOpen = ref(false)
  const pickerRef = ref(null)
  const hue = ref(0)
  const saturation = ref(100)
  const brightness = ref(100)
  const alpha = ref(100)
  const hexColorInput = ref('')


  function updateValue(event) {
    console.log( 'updateValue', event );
  }
  
  const hsbToHex = (h, s, b, a = 100) => {
    h = h / 360
    s = s / 100
    b = b / 100
    
    let r, g, b1
    const i = Math.floor(h * 6)
    const f = h * 6 - i
    const p = b * (1 - s)
    const q = b * (1 - f * s)
    const t = b * (1 - (1 - f) * s)

    switch (i % 6) {
      case 0: [r, g, b1] = [b, t, p]; break
      case 1: [r, g, b1] = [q, b, p]; break
      case 2: [r, g, b1] = [p, b, t]; break
      case 3: [r, g, b1] = [p, q, b]; break
      case 4: [r, g, b1] = [t, p, b]; break
      case 5: [r, g, b1] = [b, p, q]; break
    }

    const hex = [r, g, b1].map(x => Math.round(x * 255).toString(16).padStart(2, '0')).join('')
    if (a < 100) {
      const alpha = Math.round(a / 100 * 255).toString(16).padStart(2, '0')
      return `#${hex}${alpha}`
    }
    return `#${hex}`
  }
  
  const hexToRgb = (hex) => {
    if (!hex) return '0, 0, 0';
    hex = hex.replace(/^#/, '');
    if (hex.length === 3) {
      hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
    }
    const bigint = parseInt(hex, 16);
    const r = (bigint >> 16) & 255;
    const g = (bigint >> 8) & 255;
    const b = bigint & 255;
    return `${r}, ${g}, ${b}`;
  }
  
  const rgbToHsb = (r, g, b) => {
    r /= 255
    g /= 255
    b /= 255

    const max = Math.max(r, g, b)
    const min = Math.min(r, g, b)
    const delta = max - min

    let h, s
    const v = max

    if (delta === 0) {
      h = 0
      s = 0
    } else {
      s = delta / max
      switch (max) {
        case r: h = (g - b) / delta + (g < b ? 6 : 0); break
        case g: h = (b - r) / delta + 2; break
        case b: h = (r - g) / delta + 4; break
      }
      h /= 6
    }

    return {
      h: h * 360,
      s: s * 100,
      b: v * 100
    }
  }
  
  const parseColor = (color) => {
    if (!color || !color.startsWith('#')) {
      return { h: 0, s: 100, b: 100, a: 100 }
    }

    const hex = color.slice(1)
    const hasAlpha = hex.length === 8
    const r = parseInt(hex.slice(0, 2), 16)
    const g = parseInt(hex.slice(2, 4), 16)
    const b = parseInt(hex.slice(4, 6), 16)
    const a = hasAlpha ? Math.round(parseInt(hex.slice(6, 8), 16) / 255 * 100) : 100

    const hsb = rgbToHsb(r, g, b)
    return { h: hsb.h, s: hsb.s, b: hsb.b, a }
  }
  
  const color = computed(() => {
    return hsbToHex(hue.value, saturation.value, brightness.value, alpha.value)
  })
  
  watch(internalColor, (newColor) => {
    console.log( 'internalColor', newColor );
    if( newColor.a == 1){
      emit('update:modelValue', newColor.hex)
      emit('changed', newColor.hex)
    }else{
      emit('update:modelValue', newColor.hex8)
      emit('changed', newColor.hex8)
    }
    /* hexColorInput.value = newColor */
  })

  /* watch(color, (newColor) => {
    emit('update:modelValue', newColor)
    emit('changed', newColor)
    hexColorInput.value = newColor
  }) */
  
  watch(() => props.modelValue, (newValue) => {
    const { h, s, b, a } = parseColor(newValue)
    hue.value = h
    saturation.value = s
    brightness.value = b
    alpha.value = a
    hexColorInput.value = color.value
  }, { immediate: true })
  

  
  const togglePicker = () => {
    if( isOpen.value ){
      hidePicker()
    }else{
      showPicker()
    }
  }
  
  const showPicker = () => {
    isOpen.value = true;
    // Esc key
    document.addEventListener('keyup', handleKeyEvent);

    setTimeout(() => {
      const popup = document.querySelector('.picker-popup');
      const buttonRef = pickerRef.value;
      let buttonBottom = buttonRef.getBoundingClientRect().bottom;
      popup.style.top = buttonBottom+'px';
      popup.style.left = buttonRef.getBoundingClientRect().right-240+'px';
    }, 1);

  }
  
  const hidePicker = () => {
    isOpen.value = false;
    document.removeEventListener('keyup', handleKeyEvent);
  }

  function handleKeyEvent(event) {
    if (event.key === 'Escape') {
      isOpen.value = false;
    }
  }

  
  function handleClickOutside(event) {
    if (!pickerRef.value.contains(event.target)) {
      isOpen.value = false
    }
  }
  
  
  onMounted(() => {
    document.addEventListener('click', handleClickOutside);
  })
  
  onUnmounted(() => {
    document.removeEventListener('click', handleClickOutside);
    document.removeEventListener('keyup', handleKeyEvent);
  })
  
  </script>
  
  <style scoped>
