    cursor: pointer;
    border: 1px solid #cccccc40;
  }
  
  .picker-popup {
    position: fixed;
    padding: 10px;
    background-color: color-mix(in srgb, var(--background), #ffffff 3%);
    /* border: 1px solid #ccc; */
    box-shadow: 1px 2px 8px  rgba(0, 0, 0, 0.2);
    border: solid 1px color-mix(in srgb, var(--foreground), transparent 90%);
    z-index: 1000;
  }

  :deep(.vc-chrome) {
    background-color: color-mix(in srgb, var(--background), #ffffff 3%);
    box-shadow: none !important;
  }

  :deep(.vc-chrome-body){
    background-color: color-mix(in srgb, var(--background), #ffffff 3%);
  }

  :deep(.vc-chrome-toggle-btn) {
    width: 20px;
