  }

  :deep(.vc-chrome-fields .vc-input__input) {
    border: solid 1px color-mix(in srgb, var(--foreground), transparent 70%) !important;
    box-shadow: none;
    box-sizing: border-box;
  }
  :deep(.vc-chrome-toggle-icon) {
    margin-top: 0px;
  }
  :deep( .vc-chrome-toggle-icon-highlight ) {
    left: 2px;
