function isValidCSS(cssString) {
  // Create a temporary style element
  const style = document.createElement('style');
  
  try {
    style.textContent = cssString;
    document.head.appendChild(style);

    // Check if the style sheet has any CSS rules
    const isValid = style.sheet && style.sheet.cssRules.length > 0;

    // Remove the temporary style element
    document.head.removeChild(style);

    return isValid;
  } catch (error) {
    // If there's an error, it means the CSS is invalid
    if (style.parentNode) {
      document.head.removeChild(style);
    }
    return false;
  }
}

function applyTheme( themeObject ){
  console.log( 'applyTheme', themeObject );
  let saveUrl = `${apibase}apps/${Configuration.appid}/save?path=.theme`;
  axios.post( saveUrl, { payload: themeObject.name } )
    .then(  (response) => {
      console.log( 'applyTheme response', response );
      themes.value.active.name = themeObject.name;
      themes.value.active.asset = themeObject.asset;
      themeNameToApply.value = null;
      if( themeObject.name == 'usertheme' ){
        initialised.value = true;
      }
    })
    .catch( (error) => {
      console.log( 'applyTheme error', error );
    });
}

function customizeTheme( themeObject ){
  console.log( 'customizeTheme', themeObject );

  // Save the theme name in .theme file
  let dotThemeUrl = `${apibase}apps/${Configuration.appid}/save?path=.theme`;
  axios.post( dotThemeUrl, { payload: 'usertheme' } )
    .then(  (response) => {
      console.log( 'customizeTheme - save ".theme" response: ', response );
      
      // If .theme file saved successfully, save the theme content (previously loaded) in theme.css file
      let saveUrl = `${apibase}apps/${Configuration.appid}/save?path=${encodeURIComponent('public/css/themes/theme.css')}`;
      axios.post( saveUrl, { payload: themeObject.content } )
        .then(  (response) => {
          console.log( 'customizeTheme - save "themes/theme.css" response: ', response );
          themes.value.active.name = 'usertheme';
          themes.value.active.asset = "/css/themes/theme.css";
