      console.log( 'customizeTheme error', error );
    });
  // onThemePicked( themeObject, true );
}

async function onThemePicked( themeObject, startEditing=false ){
  if( !themeNameToApply.value ){
    let currentCss = definitionsToCss(':root.stipple-core');
    themeContentBackup.value = currentCss;
  }

  showThemeError('');
  
  console.log( 'onThemePicked', themeObject.assetFullPath );
  if( themeObject.assetFullPath ){
    fetch(themeObject.assetFullPath)
      .then(response => {
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        return response.text();
      })
      .then(data => {
        // Success
        if( isValidCSS(data) ){
          //themeContentToApply.value = data;
          //showThemeOverwriteWarning.value = true;
          
          themeObject.content = data;
          let templateCssString = data;
          initializeFromThemeCssFile( templateCssString );
          assignVariables(); 
          if( startEditing ){
            initialised.value = true;
            themeSelectorVisible.value = false;
          }
          //unsavedChanges.value = true;
        }else{
          console.error( 'Invalid CSS' );
          throw new Error( 'Invalid CSS' );
        }
      })
      .catch(error => {
        console.error('Error fetching theme:', error);
        //let errorMessage = `Error loading theme<br/>`;
        let errorMessage = '';

        if (error.name === 'TypeError' && error.message.includes('Failed to fetch')) {
          errorMessage += 'CSS File not found CSS File not found CSS File not found';
        }else{
          errorMessage += error.message;
        }
        showThemeError( errorMessage );
      })
      .finally( () => {
        themeNameToApply.value = themeObject;
        console.log( 'onThemePicked - finally', themeNameToApply.value );
      });
  }else{
    showThemeError( `Missing asset path` );
  }

}

function showThemeError(error){
  themeError.value = error;
}

