function setUpdatedThemes( newThemes ){
  themes.value = newThemes;
}

function refreshThemeList(){
  console.log( 'refreshThemeList' );
  
  // Build app's base path and remove ending slash if present
  let appBasePath = Configuration.getAppAssetsBaseUrl('http', window.appData.value.port);
  if( appBasePath[appBasePath.length-1] == '/' ){
    appBasePath = appBasePath.substring(0, appBasePath.length-1);
  }

  // Get the page data from GB's API
  let pageDataUrl = `${apibase}apps/${Configuration.appid}/pages`;
  axios.get( pageDataUrl )
    .then( (result) => {
      let currentPage = result.data.pages[Configuration.currentPageIndex];
      let newThemes = currentPage.themes;

      // Build full paths for the active theme
      if( newThemes && newThemes.active ){
        if( newThemes.active.asset.startsWith('/') ){
          newThemes.active.assetFullPath = appBasePath + newThemes.active.asset;
        }else{
          newThemes.active.assetFullPath = newThemes.active.asset;
        }
      }
      // Build full paths for the registered themes
      if( newThemes && newThemes.registered ){
        newThemes.registered.forEach((theme) => {
          if( theme.asset.startsWith('/') ){
            theme.assetFullPath = appBasePath + theme.asset;
          }else{
            theme.assetFullPath = theme.asset;
          }
        });
      }
      // store the new list of themes
      setUpdatedThemes( newThemes );
    })
    .catch( (error) => {
      console.log( 'refreshThemeList error', error );
    });
}

function toggleThemeSelector(){
  showThemeSelector( !themeSelectorVisible.value );
}

function showThemeSelector(show){ 
  console.log( 'showThemeSelector', show, themeNameToApply.value );
  //if( show && themeNameToApply.value ){
  if( show ){
    console.log( 'showThemeSelector - will refresh theme list' );
    refreshThemeList();
  }else{
    if( themeNameToApply.value ){
      console.log( 'showThemeSelector - will discard' );
      discardPreviewedTheme();
    }
  }
  showThemeOverwriteWarning.value = false;
  themeNameToApply.value = '';
  themeSelectorVisible.value = show;
  themeError.value = '';
}

