function storePropertyDefaults(){
  themeItems.value.groups.forEach((group) => {
    group.rules.forEach((rule) => {
      rule.properties.forEach((property) => {
        property.defaultValue = property.value;
      });
    });
  });
}

function discardPreviewedTheme(){
  themeNameToApply.value = '';

  
  if( themeContentBackup.value ){
    console.log( 'discardPreviewedTheme A (backup)' );
    initializeFromThemeCssFile( themeContentBackup.value );
  }else{
    console.log( 'discardPreviewedTheme B (original)' );
    initializeFromThemeCssFile( originalThemeContent.value );
  }
  assignVariables(); 
}

function initializeFromThemeCssFile( cssContent, firstTime=false ){
    console.log( '[ThemeEditor] initializeFromThemeCssFile()', cssContent.length );
    if( cssContent == '' ){
      emit( 'changed', '' );
      return;
    }
    let parsedCss = parseCSS( cssContent );
    let incomingBySelector = {};
    parsedCss.forEach((item) => {
        if(!incomingBySelector[item.selector]) {
            incomingBySelector[item.selector] = {};
        }
        incomingBySelector[item.selector][item.propertyName] = item.value;
    });

    let groups = themeItems.value.groups;
    groups.forEach((group) => {
        group.rules.forEach((rule) => {
            let selector = rule.selector;
            rule.properties.forEach((property) => {
                let inputObjectSelector = incomingBySelector[selector];
                if( inputObjectSelector ){
                    let inputObjectProperty = inputObjectSelector[property.propertyName];
                    if (inputObjectProperty) {
                        property.value = inputObjectProperty;
                    }
                }
            });
        });
    });
    if( firstTime ){
      originalThemeContent.value = cssContent;
    }
    // Backup the theme items
    storePropertyDefaults();
    if( firstTime ){
      setTimeout(() => {
        initialised.value = true;
      }, 100);
    }
}




// ==========================================================================
//                          CSS Parsing Functions                           
// ==========================================================================

// Takes the raw css text from theme.cssand parses it into an array of objects
// --------------------------------------------------------------------------
function parseCSS(cssText) {
  const result = [];
  // Extract the :root.stipple-core block and other CSS rules
  const rootRegex = /:root\.stipple-core\s*{([\s\S]*?)}/;
  const cssRulesRegex = /([^{}]+){([^}]+)}/g;
  
  // Process :root.stipple-core block
  const rootMatch = rootRegex.exec(cssText);
  if (rootMatch) {
    const propertiesBlob = rootMatch[1].trim();
    const properties = propertiesBlob.split(';').filter(property => property.trim() !== '');

    properties.forEach(property => {
      const [propertyName, value] = property.split(':').map(part => part.trim());
      result.push({ selector: ':root.stipple-core', propertyName, value });
    });
  }

  // Process other CSS rules
  let ruleMatch;
  while ((ruleMatch = cssRulesRegex.exec(cssText)) !== null) {
    const selector = ruleMatch[1].trim();
    const propertiesBlob = ruleMatch[2].trim();
    const properties = propertiesBlob.split(';').filter(property => property.trim() !== '');

    properties.forEach(property => {
      const [propertyName, value] = property.split(':').map(part => part.trim());
      result.push({ selector, propertyName, value });
    });
  }
  // Iterate result and when css vars found, remove "var(" and ")"
  result.forEach((item) => {
    if (item.value?.startsWith('var(')) {
      item.value = item.value.replace('var(', '').replace(')', '');
    }
  });
  return result;
}


// Toggles the mode of a property between a value and a variable
// --------------------------------------------------------------------------
function togglePropMode(item) {
  if( valueIsVar( item.value) ){
    let propDefinition = CssPropDefs[item.propertyName];
    if( propDefinition ){
      item.value = propDefinition.default;
    }else{
      console.error("[ThemeEditor] No property definition for ", item.propertyName )
    }
  }else{
    item.value = '--undefined';
  }
  assignVariables(); 
}


// Checks if a value is a variable
// --------------------------------------------------------------------------
function valueIsVar( value){
  let result =  typeof value == 'string' && value.startsWith('--');
  return result;
}


// ==========================================================================
//                          Complex-number properties                        
// ==========================================================================

// Converts a value to a numeric value if possible
// --------------------------------------------------------------------------
function getNumericValue(item) {
    return parseFloat(item.value) || ''; // Extracts numeric part or returns an empty string
};

// Extracts the unit part of a value (px, %, etc.)
// --------------------------------------------------------------------------
function getUnitValue(item) {
    const match = item.value.match(/[a-zA-Z%]+$/); // Matches the unit part
    return match ? match[0] : 'px'; // Returns the unit part or an empty string if not found
};

// Updates the value of a property when the numeric value changes
// --------------------------------------------------------------------------
function updateNumericValue(event, item) {
    const numericValue = event.target.value;
    const unitValue = this.getUnitValue(item);
    if( numericValue != '')
      item.value = `${numericValue}${unitValue}`; // Combines the new numeric value with the current unit
    else
      item.value = numericValue;
    this.assignVariables(); 
};

// Updates the value of a property when the unit changes
// --------------------------------------------------------------------------
function updateUnitValue(event, item) {
    const unitValue = event.target.value;
    const numericValue = this.getNumericValue(item);
    if( numericValue != '')
      item.value = `${numericValue}${unitValue}`; // Combines the new numeric value with the current unit
    else
      item.value = numericValue;
    this.assignVariables(); 
};


// ==========================================================================
//                          Save and Apply Functions                        
// ==========================================================================

// Saves the document to the server
// --------------------------------------------------------------------------
function saveDocument( emptyContent=false ){
  console.log( '[ThemeEditor] saveDocument' );
  unsavedChanges.value = false;
  let encodedFilePath = encodeURIComponent( props.filepath );
  let saveUrl = `${ props.endpoint }save?path=${ encodedFilePath }`;

  let cssRules;
  if( emptyContent == true ){
    cssRules = '';
  }else{
    cssRules = templateCss;
    cssRules = cssRules.replace( '/* {{ themeVariables }} */', definitionsToCss(':root.stipple-core') );
  }
  console.log( '[ThemeEditor] saveUrl', saveUrl );
  
  axios.post( saveUrl, { payload: cssRules } )
    .then(  (response) => {
      console.log("[ThemeEditor] html-save callback: ", encodedFilePath );
      // Catch server errors
      if( response.status != 200 ){
        console.log( "[ThemeEditor] Error saving template: ", response );
        return;
      }      
      if( emptyContent == true ){
        window.location.reload();
      }else{
        storePropertyDefaults();
      }
    } )
    .catch( (error) => {
      console.log("[ThemeEditor] error saving HTML: ", encodedFilePath );
      console.log( "[ThemeEditor] ERROR saving template file response: ", error );
      // Catch server errors
      console.log( "[ThemeEditor] Error saving template, network error: ", error );
      showApiErrorAlert( `There was an issue saving your changes (Network error). If the problem persists please try reloading this window.` );
    });
}

function showApiErrorAlert(error){
  window.parent.postMessage( {command:"showApiErrorAlert", message:error }, "*" );
}

// Clears the theme
// --------------------------------------------------------------------------
function clearTheme(){
  unsavedChanges.value = false;
  //saveDocument( true );
  resetAllProperties();
}

// ==========================================================================
//                          CSS Definitions Functions                        
// ==========================================================================

// Gets the definition of a property
// --------------------------------------------------------------------------
function getCssPropDef( propertyName ){
  let propDef = CssPropDefs[propertyName];
  return propDef
}

// Injects the definitions of the properties into the theme items
// --------------------------------------------------------------------------
function injectCssPropDefinitions(){
  themeItems.value.groups.forEach((group) => {
    group.rules.forEach((rule) => {
      rule.properties.forEach((property) => {
        let propDef = getCssPropDef(property.propertyName);
        if (propDef) {
          property.type = propDef.type;
          if( propDef.options )
            property.options = propDef.options;
          if( propDef.units )
            property.units = propDef.units;
        }
      });
    });
  });
}

// Gets the list of css variables
// --------------------------------------------------------------------------
function getCssVariables( item ){
    let results = [];
    if( item.propertyName == 'font-size'){
      themeItems.value.groups.forEach((group) => {
        group.rules.forEach((rule) => {
            rule.properties.forEach((property) => {
                if( property.isVar && property.type=='text' ){
                    results.push(property);
                }
            });
        });
      });
    }else{
      themeItems.value.groups.forEach((group) => {
        group.rules.forEach((rule) => {
            rule.properties.forEach((property) => {
                if( property.isVar && !property.hide && property.type=='color' ){
                    results.push(property);
                }
            });
        });
      });
      results = results.sort((a, b) => a.label.localeCompare(b.label));
    }
  return results;

}

// Converts the theme items into a css string for saving
// --------------------------------------------------------------------------
function definitionsToCss(rootSelector='#demoContent'){
  let output = ''; // `${rootSelector}{\n`;
  themeItems.value.groups.forEach((group) => {
    group.rules.forEach((rule) => {
      output += `  ${rule.selector}{\n`;
      rule.properties.forEach((property) => {
          if( property.value == null || property.value.startsWith == null ){
            //debugger;
          }
          if( property.value == '' ){
            // skip
          }
          else if( property.value.startsWith('--') )
            output += `    ${property.propertyName}: var(${property.value});\n`;
          else
            output += `    ${property.propertyName}: ${property.value};\n`;
        });
        output += `  }\n`;
    });
  });
  return output;
}

// Handles the change of a property value
// --------------------------------------------------------------------------
function onPropValueChanged(){
    if(!initialised.value){
        return;
    }
    unsavedChanges.value = true;
    assignVariables();
}

// Assigns the variables to the css rules
// --------------------------------------------------------------------------
function assignVariables(){
  let cssRules = templateCss;
  cssRules = cssRules.replace( '/* {{ themeVariables }} */', definitionsToCss(':root.stipple-core') );
  emit( 'changed', cssRules );
}

function resetAllProperties(){
  themeItems.value.groups.forEach((group) => {
    group.rules.forEach((rule) => {
      rule.properties.forEach((property) => {
        resetProperty(rule, property);
      });
    });
  });
}
// Resets a property to its default value
// --------------------------------------------------------------------------
function resetProperty( rule, item){
  let defaultValue = item.defaultValue;
  item.value = defaultValue;
  
  onPropValueChanged();
}


onMounted(() => {
  refreshThemeList();

});

</script>


